import { useState } from "react";

export function App() {
  const [command, setCommand] = useState("");
  const [status, setStatus] = useState("idle");
  function submit(event: React.FormEvent) { event.preventDefault(); setStatus(`Ran ${command}`); }
  return (
    <form onSubmit={submit}>
      <input data-testid="command" value={command} onChange={(event) => setCommand(event.target.value)} />
      <button data-testid="keyboard-submit" type="submit">Keyboard submit</button>
      <span data-testid="command-status">{status}</span>
    </form>
  );
}
